(()=>{
  const body = document.body.textContent;
  const h3 = [...document.querySelectorAll('h3')].map(h => h.textContent.trim());
  const rows = [...document.querySelectorAll('tbody tr')].map(r => r.textContent.replace(/\s+/g,' '));
  const pick = (re) => rows.filter(r => re.test(r)).map(r => r.slice(0, 500));
  return JSON.stringify({
    title: document.title,
    tallyTiles: document.querySelectorAll('.tally div').length,
    headings: h3,
    // present
    mastheadReRuns: /4 accepted, each re-driven once at the committed revision; 5 excluded, 1 diagnostic/.test(body),
    recheckSection: h3.some(t => /re-driven at the committed revision/.test(t)),
    d3Reading: /"answerDelivered":true,"workflowIncompleteError":false,"toolsRun":0,"replyLength":238/.test(body),
    d8ReadonlyReading: /"navigateToolsSucceeded":0,"navigateAttempts":2,"refusalVisible":true/.test(body),
    d8AskReading: /"cardTitle":"The assistant wants to: Move the workspace","cardSummary":"measure","storePending":null,"mode":"ask","working":true,"elapsedMs":10101/.test(body),
    d4Reading: /15\.1 s after the send/.test(body),
    recheckRunNames: ['qa-recheck-d3','qa-recheck-d8-readonly','qa-recheck-d8-ask','qa-recheck-d4'].every(n => body.includes(n)),
    revisionGap: /Eleven of the seventeen files\s+in this change/.test(body) && /110\s*s before the first commit/.test(body) && /three commits\s+were made at 15:18:14/.test(body),
    screenshotDisclosure: /Seven captures under/.test(body) && /now\s+hold the committed-revision frames/.test(body) && /none of the four now matches/.test(body),
    recheckScenariosIdentical: /byte-identical to its accepted\s+counterpart/.test(body),
    tabulateReRuns: /4 re-runs at the committed revision/.test(body),
    asksFourRuns: /recorded, not inferred, and in four runs/.test(body),
    batchBail: /batch --bail/.test(body),
    readonlyOnly: /Read-only mode would have stopped/.test(body),
    devServerStopped: /was stopped through its own identity-checked path once the last run that/.test(body),
    previewUntouched: /preview on\s*:8080/.test(body),
    // gone — the retention claim the dev-server stop replaced
    oldDevServerRetained: /left running with its identity verified/.test(body),
    // gone — the four corrections made after the previous render
    oldChangedAfterThat: /changed after that/.test(body),
    oldRecheckShotsInRunner: /screenshots and the archived scenarios they consumed are in/.test(body),
    oldRenderOrder: /once the last\s+scenario run and this render were both finished/.test(body),
    oldStopLineQuote: /PID 50804 gone, port 8085 released/.test(body),
    // gone
    oldMasthead: /8 close operations/.test(body),
    oldCloseShare: /8 of 18/.test(body),
    oldReadonlyAsk: /readonly and ask mode/.test(body),
    oldFiftySeven: /all 57 opcodes attempted/.test(body),
    oldTwoRuns: /recorded, not inferred, and in two runs/.test(body),
    // the retracted cold-graph figure stays only as the disclosure that no artifact records it
    coldGraphDisclosed: /76\.2/.test(body) && /not established by any artifact/.test(body),
    // the rows themselves
    tabulateRow: pick(/4 re-runs at the committed revision/),
    bailRow: pick(/batch --bail/),
    horizontalOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1,
    bodyBg: getComputedStyle(document.body).backgroundColor
  });
})()

(()=>{
  const imgs = [...document.images].map(i => ({w: i.naturalWidth, h: i.naturalHeight, shown: Math.round(i.getBoundingClientRect().width)}));
  return JSON.stringify({images: imgs, allLoaded: imgs.every(i => i.w > 0), fontCount: document.fonts.size});
})()

(()=>{
  const h = [...document.querySelectorAll('h3')].find(x => /re-driven at the committed revision/.test(x.textContent));
  if (!h) return JSON.stringify({error: 'recheck heading not found'});
  const y = Math.round(h.getBoundingClientRect().top + window.scrollY);
  window.scrollTo(0, y - 40);
  return JSON.stringify({scrolledTo: y, heading: h.textContent.trim()});
})()

(()=>{
  window.scrollTo(0,0);
  const over = [...document.querySelectorAll('*')].filter(e => e.getBoundingClientRect().width > document.documentElement.clientWidth + 2).map(e => e.tagName + '.' + e.className).slice(0, 8);
  return JSON.stringify({narrowOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1, over});
})()
